INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('65a76c6b-c1a8-46a3-907d-01704c71580b', 'a1b2c3d4-0001-4000-8000-000000000001', 3, 'A Palavra que Transforma', 'Introdução à Bíblia', '{"bible_ref": "Sl 119,105", "reflection": "A Palavra de Deus \u00e9 l\u00e2mpada para nossos passos."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8a7d7d4c-d0ca-400c-9da2-442febc6deaa', 'a1b2c3d4-0001-4000-8000-000000000001', 4, 'Exame de Consciência', 'Olhar para dentro com honestidade', '{"prompt": "O que mais me afasta de Deus no meu dia a dia?", "guidance": "Seja honesto consigo mesmo, sem julgamento."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('38db9dd6-8288-4cb7-8ec2-1581cf639997', 'a1b2c3d4-0001-4000-8000-000000000001', 5, 'Os Sacramentos', 'Fontes de graça', '{"reflection": "Os sacramentos s\u00e3o sinais eficazes da gra\u00e7a divina.", "catechism_ref": "CIC 1210"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bfd8ee6c-4069-42a9-85ec-f5558311d60f', 'a1b2c3d4-0003-4000-8000-000000000003', 1, 'O Chamado à Contemplação', 'São João da Cruz', '{"text": "A alma que deseja alcan\u00e7ar a perfei\u00e7\u00e3o deve primeiro passar pela noite escura dos sentidos.", "source": "S\u00e3o Jo\u00e3o da Cruz"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7022626f-dd2e-4568-91b1-4eeccfc1b688', 'a1b2c3d4-0003-4000-8000-000000000003', 2, 'Oração de Quietude', 'Santa Teresa de Ávila', '{"instruction": "Feche os olhos, aquiete a mente e simplesmente esteja na presen\u00e7a de Deus por 20 minutos."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('13e35790-a1aa-4ac7-bd61-6bdf6572b923', 'a1b2c3d4-0003-4000-8000-000000000003', 3, 'Lectio Divina Profunda', 'A Palavra que penetra a alma', '{"method": "Leia, medite, ore, contemple. Repita at\u00e9 sentir a Palavra falar ao seu cora\u00e7\u00e3o.", "bible_ref": "Jo 15,1-8"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d596428b-8081-4845-b0f1-581e8b574516', 'a1b2c3d4-0003-4000-8000-000000000003', 4, 'Diário Místico', 'Registre suas moções interiores', '{"prompt": "O que o Esp\u00edrito Santo est\u00e1 falando ao seu cora\u00e7\u00e3o? Que movimentos interiores voc\u00ea percebe?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('1e36c32b-9c60-4665-a21b-89eba8bdab35', 'a1b2c3d4-0003-4000-8000-000000000003', 5, 'A União com Deus', 'O fim da jornada é o começo', '{"text": "O importante n\u00e3o \u00e9 pensar muito, mas amar muito.", "source": "Santa Teresa de \u00c1vila", "catechism_ref": "CIC 2709"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0001-4000-8000-000000000001', 'a1b2c3d4-0004-4000-8000-000000000004', 1, 'O Reconhecimento', 'Olhar para dentro com coragem', '{"intro": "Toda liberta\u00e7\u00e3o come\u00e7a com um ato de coragem: reconhecer que algo nos prende. N\u00e3o se trata de fraqueza \u2014 \u00e9 a mais profunda honestidade diante de Deus. Santo Agostinho escreveu: \"Fizeste-nos para Ti, Senhor, e o nosso cora\u00e7\u00e3o est\u00e1 inquieto enquanto n\u00e3o repousar em Ti.\" Essa inquieta\u00e7\u00e3o \u00e9 o primeiro sinal de que h\u00e1 correntes a serem rompidas.\n\nHoje, voc\u00ea \u00e9 convidado a parar. N\u00e3o para se julgar, mas para se ver. Como quem olha no espelho pela primeira vez sem desviar o olhar. O que te prende? Medo? Ressentimento? V\u00edcios? Padr\u00f5es que se repetem? Nomeie, sem vergonha. Deus j\u00e1 sabe \u2014 Ele espera que voc\u00ea tamb\u00e9m saiba.", "prayer": "Senhor, d\u00e1-me a coragem de olhar para dentro sem fugir. Mostra-me as correntes que eu mesmo n\u00e3o enxergo. N\u00e3o quero viver mais na superf\u00edcie \u2014 quero a verdade que liberta. Am\u00e9m.", "practice": "Encontre um lugar silencioso. Feche os olhos por 5 minutos e pe\u00e7a a Deus que ilumine uma \u00e1rea da sua vida onde voc\u00ea n\u00e3o \u00e9 livre. N\u00e3o force \u2014 apenas escute. Depois, escreva no seu di\u00e1rio o que veio ao cora\u00e7\u00e3o.", "scripture": "\"Conhecereis a verdade, e a verdade vos libertar\u00e1.\" \u2014 Jo 8,32\n\n\"Sonda-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "1. Que padr\u00f5es se repetem na sua vida e te causam sofrimento?\n2. H\u00e1 algo que voc\u00ea evita olhar de frente? O que seria?\n3. Se Deus pudesse te dizer uma verdade agora, o que voc\u00ea acha que Ele diria?", "journal_prompt": "O que eu reconhe\u00e7o hoje que me prende? Qual \u00e9 a primeira corrente que consigo nomear?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0002-4000-8000-000000000002', 'a1b2c3d4-0004-4000-8000-000000000004', 2, 'As Correntes Invisíveis', 'Identificando o que nos aprisiona', '{"intro": "Existem pris\u00f5es com grades de ferro \u2014 e existem pris\u00f5es feitas de pensamentos, h\u00e1bitos e feridas. As mais perigosas s\u00e3o as que n\u00e3o vemos. S\u00e3o as narrativas que repetimos sobre n\u00f3s mesmos: \"eu n\u00e3o mere\u00e7o\", \"sempre ser\u00e1 assim\", \"Deus n\u00e3o se importa comigo\".\n\nS\u00e3o Tom\u00e1s de Aquino ensina que o pecado obscurece a raz\u00e3o e enfraquece a vontade. Mas n\u00e3o apenas o pecado nos prende: o medo, a vergonha, o orgulho, a autossufici\u00eancia \u2014 tudo isso cria correntes invis\u00edveis.\n\nHoje, vamos mapear essas correntes. N\u00e3o para nos condenar, mas para trazer \u00e0 luz o que vive na escurid\u00e3o.", "prayer": "Esp\u00edrito Santo, ilumina os cantos escuros da minha alma. Mostra-me as mentiras em que acreditei. Substitui cada corrente pela Tua verdade. Eu quero ser livre \u2014 verdadeiramente livre. Am\u00e9m.", "practice": "Pegue uma folha de papel e divida em duas colunas: \"O que eu acredito sobre mim\" e \"O que Deus diz sobre mim\". Preencha com honestidade. Compare as duas colunas e perceba onde est\u00e3o as distor\u00e7\u00f5es.", "scripture": "\"Onde est\u00e1 o Esp\u00edrito do Senhor, a\u00ed h\u00e1 liberdade.\" \u2014 2Cor 3,17\n\n\"N\u00e3o vos conformeis com este mundo, mas transformai-vos pela renova\u00e7\u00e3o da vossa mente.\" \u2014 Rm 12,2", "reflection": "1. Que mentiras voc\u00ea acredita sobre si mesmo h\u00e1 anos?\n2. Existe algum medo que controla suas decis\u00f5es?\n3. H\u00e1 algum relacionamento ou situa\u00e7\u00e3o que te mant\u00e9m preso(a) a um padr\u00e3o destrutivo?", "journal_prompt": "Quais s\u00e3o as mentiras que descobri que acreditava sobre mim? Como elas afetaram minhas escolhas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0003-4000-8000-000000000003', 'a1b2c3d4-0004-4000-8000-000000000004', 3, 'O Espelho da Alma', 'Enfrentando a verdade sobre quem somos', '{"intro": "O exame de consci\u00eancia \u00e9 a pr\u00e1tica mais antiga e poderosa da vida crist\u00e3. Santo In\u00e1cio de Loyola o considerava mais importante que a pr\u00f3pria ora\u00e7\u00e3o \u2014 porque sem verdade, a ora\u00e7\u00e3o se torna fuga.\n\nHoje, vamos fazer algo radical: olhar para a alma como se olh\u00e1ssemos num espelho sem filtros. N\u00e3o \u00e9 autocondena\u00e7\u00e3o \u2014 \u00e9 autoconsci\u00eancia na presen\u00e7a de Deus. Como diz Santa Teresa de \u00c1vila: \"O autoconhecimento \u00e9 a porta da ora\u00e7\u00e3o.\"", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. N\u00e3o me deixes fugir da verdade. D\u00e1-me a gra\u00e7a de me ver como Tu me v\u00eas \u2014 com amor e com verdade. Am\u00e9m.", "practice": "Fa\u00e7a o Exame de Consci\u00eancia de Santo In\u00e1cio: 1) Agrade\u00e7a as gra\u00e7as do dia. 2) Pe\u00e7a luz para ver seus atos. 3) Reveja as \u00faltimas 24 horas. 4) Pe\u00e7a perd\u00e3o pelo que errou. 5) Proponha-se a melhorar amanh\u00e3.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o. Prova-me e conhece os meus pensamentos ansiosos. V\u00ea se h\u00e1 em mim algum caminho mau e guia-me pelo caminho eterno.\" \u2014 Sl 139,23-24", "reflection": "1. Se algu\u00e9m filmasse sua vida interior por uma semana, o que veria?\n2. Qual \u00e9 o pecado que voc\u00ea mais justifica para si mesmo?\n3. H\u00e1 algo que voc\u00ea nunca confessou \u2014 n\u00e3o por esquecimento, mas por vergonha?", "journal_prompt": "O que o espelho da alma me mostrou hoje? O que preciso levar ao sacramento da confiss\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0004-4000-8000-000000000004', 'a1b2c3d4-0004-4000-8000-000000000004', 4, 'A Porta Estreita', 'O caminho da renúncia e da entrega', '{"intro": "\"Entrai pela porta estreita\" \u2014 esta palavra de Jesus n\u00e3o \u00e9 um convite ao sofrimento gratuito, mas \u00e0 escolha consciente. A porta larga \u00e9 a comodidade, o \"deixa pra l\u00e1\", o conformismo espiritual. A porta estreita \u00e9 a decis\u00e3o de morrer para si mesmo.\n\nS\u00e3o Jo\u00e3o da Cruz chamou isso de \"noite escura da alma\" \u2014 o momento em que Deus nos convida a soltar o que nos d\u00e1 falsa seguran\u00e7a para encontrar a verdadeira. \u00c9 doloroso. Mas \u00e9 o \u00fanico caminho para a liberdade.", "prayer": "Senhor Jesus, Tu passaste pela porta estreita da Cruz por amor a mim. D\u00e1-me a coragem de fazer o mesmo. N\u00e3o quero a comodidade que me afasta de Ti. Quero a estreiteza que me aproxima. Am\u00e9m.", "practice": "Escolha uma ren\u00fancia concreta para esta semana. Pode ser algo pequeno: um v\u00edcio digital, uma comodidade, um padr\u00e3o de consumo. Ofere\u00e7a essa ren\u00fancia a Deus como sacrif\u00edcio de amor. Registre como se sente ao longo dos dias.", "scripture": "\"Entrai pela porta estreita, pois larga \u00e9 a porta e espa\u00e7oso o caminho que conduz \u00e0 perdi\u00e7\u00e3o, e muitos s\u00e3o os que entram por ela.\" \u2014 Mt 7,13\n\n\"Se algu\u00e9m quiser vir ap\u00f3s mim, negue-se a si mesmo, tome a sua cruz e siga-me.\" \u2014 Mt 16,24", "reflection": "1. O que voc\u00ea mais tem medo de perder? Essa coisa tem poder sobre voc\u00ea?\n2. Que conforto ou h\u00e1bito Deus est\u00e1 te pedindo para soltar?\n3. O que significa \"morrer para si mesmo\" na sua vida concreta?", "journal_prompt": "Qual ren\u00fancia escolhi para esta semana? O que sinto ao pensar em abrir m\u00e3o disso?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0005-4000-8000-000000000005', 'a1b2c3d4-0004-4000-8000-000000000004', 5, 'O Perdão Radical', 'Quebrando a maior corrente de todas', '{"intro": "Se h\u00e1 uma corrente que prende mais almas do que qualquer outra, \u00e9 a falta de perd\u00e3o. O ressentimento \u00e9 um veneno que bebemos esperando que o outro morra. E no entanto, quantos de n\u00f3s carregamos m\u00e1goas de anos \u2014 contra pais, amigos, ex-parceiros, contra n\u00f3s mesmos, e at\u00e9 contra Deus?\n\nJesus n\u00e3o sugeriu o perd\u00e3o \u2014 Ele o ordenou. E n\u00e3o uma vez, mas setenta vezes sete. Porque o perd\u00e3o n\u00e3o \u00e9 um sentimento: \u00e9 uma decis\u00e3o da vontade, sustentada pela gra\u00e7a. Hoje, vamos enfrentar a maior corrente.", "prayer": "Pai misericordioso, Tu que perdoaste a humanidade inteira do alto da Cruz, d\u00e1-me a gra\u00e7a de perdoar quem me feriu. Cura as feridas que carrego. Liberta-me do peso do ressentimento. Eu escolho perdoar \u2014 n\u00e3o porque seja f\u00e1cil, mas porque Tu me pedes. Am\u00e9m.", "practice": "Escreva uma carta de perd\u00e3o (que n\u00e3o precisa ser enviada). Dirija-se \u00e0 pessoa que te feriu. Descreva a dor, reconhe\u00e7a a ferida, e ent\u00e3o escreva as palavras: \"Eu escolho te perdoar. Entrego esta dor a Deus.\" Depois, reze um Pai-Nosso lentamente, detendo-se em \"perdoai as nossas ofensas assim como n\u00f3s perdoamos a quem nos tem ofendido.\"", "scripture": "\"Se perdoardes aos homens as suas ofensas, vosso Pai celeste tamb\u00e9m vos perdoar\u00e1.\" \u2014 Mt 6,14\n\n\"Pai, perdoa-lhes, porque n\u00e3o sabem o que fazem.\" \u2014 Lc 23,34", "reflection": "1. Quem voc\u00ea ainda n\u00e3o perdoou de verdade?\n2. Voc\u00ea se perdoou pelos seus pr\u00f3prios erros?\n3. H\u00e1 alguma m\u00e1goa contra Deus \u2014 por algo que Ele permitiu acontecer?", "journal_prompt": "Quem eu perdoei hoje? Como me senti ao escrever a carta de perd\u00e3o? O que mudou dentro de mim?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0006-4000-8000-000000000006', 'a1b2c3d4-0004-4000-8000-000000000004', 6, 'A Liberdade dos Filhos', 'Vivendo como quem foi libertado', '{"intro": "Voc\u00ea chegou ao fim desta jornada \u2014 mas na verdade, este \u00e9 o come\u00e7o. A liberdade que Cristo oferece n\u00e3o \u00e9 aus\u00eancia de dificuldades: \u00e9 a presen\u00e7a de Deus em cada uma delas. Como diz S\u00e3o Paulo: \"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\"\n\nAgora que voc\u00ea reconheceu suas correntes, olhou de frente para a verdade, passou pela porta estreita e perdoou \u2014 \u00e9 hora de viver como filho(a) livre. N\u00e3o como escravo do medo, da culpa ou do passado. Mas como herdeiro(a) do Reino.", "prayer": "Senhor Jesus Cristo, Libertador da minha alma, obrigado(a) por esta jornada. Obrigado(a) por me mostrar a verdade, mesmo quando doeu. Obrigado(a) por romper as correntes que me prendiam. Eu me comprometo a viver na liberdade que Tu me deste. N\u00e3o voltarei atr\u00e1s. Am\u00e9m.", "practice": "Crie um \"plano de liberdade\": 1) Uma pr\u00e1tica di\u00e1ria de ora\u00e7\u00e3o (5 min). 2) Um exame de consci\u00eancia semanal. 3) Confiss\u00e3o mensal. 4) Uma pessoa de confian\u00e7a para prestar contas. Comprometa-se com este plano por 30 dias.", "scripture": "\"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\" \u2014 Gl 5,1\n\n\"Se o Filho vos libertar, verdadeiramente sereis livres.\" \u2014 Jo 8,36", "reflection": "1. O que mudou em voc\u00ea desde o in\u00edcio desta jornada?\n2. Quais correntes foram rompidas? Quais ainda precisam de trabalho?\n3. Como voc\u00ea vai manter essa liberdade no dia a dia?", "journal_prompt": "O que esta jornada significou para mim? Qual \u00e9 meu compromisso a partir de agora? Que palavras eu diria a algu\u00e9m que est\u00e1 come\u00e7ando onde eu comecei?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8197c079-be7b-4fe0-b6b6-52fca2c2ad2d', 'a1b2c3d4-1111-4000-8000-000000000001', 1, 'O Despertar Interior', 'Por que uma rotina espiritual?', '{"intro": "Antes de tudo, precisamos entender: uma rotina espiritual n\u00e3o \u00e9 uma pris\u00e3o de hor\u00e1rios \u2014 \u00e9 uma estrutura que liberta. Assim como um rio precisa de margens para fluir com for\u00e7a, nossa vida espiritual precisa de ritmo para crescer. Santo In\u00e1cio de Loyola dizia que a ordem do dia \u00e9 a primeira vit\u00f3ria contra o caos interior. Quando estabelecemos momentos fixos de encontro com Deus, deixamos de depender da emo\u00e7\u00e3o e passamos a viver pela decis\u00e3o.", "prayer": "Senhor, ensina-me a Te buscar n\u00e3o quando sobra tempo, mas como a primeira coisa do meu dia. Que eu aprenda a construir minha vida sobre o alicerce da Tua presen\u00e7a. Am\u00e9m.", "practice": "Escolha dois hor\u00e1rios fixos hoje \u2014 manh\u00e3 e noite \u2014 e reserve pelo menos 5 minutos em cada para sil\u00eancio e ora\u00e7\u00e3o.", "scripture": "\"Buscai primeiro o Reino de Deus e a sua justi\u00e7a, e todas estas coisas vos ser\u00e3o acrescentadas.\" \u2014 Mt 6,33", "reflection": "Em que momentos do seu dia voc\u00ea sente que Deus est\u00e1 mais distante? Que horas seriam ideais para reservar um encontro di\u00e1rio com Ele?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6df20be7-3248-4db0-88cb-13265ffc745b', 'a1b2c3d4-1111-4000-8000-000000000001', 2, 'Oração da Manhã', 'Começando o dia com Deus', '{"intro": "A tradi\u00e7\u00e3o crist\u00e3 sempre valorizou a ora\u00e7\u00e3o matutina. Os monges beneditinos iniciam o dia com as Laudes antes do sol nascer. Por qu\u00ea? Porque oferecer as prim\u00edcias do dia a Deus \u00e9 reconhecer que tudo vem Dele. Uma ora\u00e7\u00e3o matinal simples \u2014 mesmo de 5 minutos \u2014 transforma a qualidade do seu dia inteiro. N\u00e3o precisa ser longa; precisa ser sincera.", "prayer": "Deus de toda gra\u00e7a, que as primeiras palavras da minha boca sejam de louvor. Que eu aprenda com Jesus a buscar-Te antes de tudo. Am\u00e9m.", "practice": "Amanh\u00e3, ao despertar, antes de olhar o celular, fa\u00e7a esta ora\u00e7\u00e3o: Pai, entrego este dia nas Tuas m\u00e3os. Guia meus passos, meus pensamentos e minhas palavras.", "scripture": "\"De manh\u00e3, por\u00e9m, tendo-se levantado muito cedo, saiu e foi a um lugar deserto, e ali orava.\" \u2014 Mc 1,35", "reflection": "Como voc\u00ea normalmente come\u00e7a seu dia? O que mudaria se os primeiros 5 minutos fossem dedicados a Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bfe0188e-4821-488d-8502-86fa2e397217', 'a1b2c3d4-1111-4000-8000-000000000001', 3, 'Lectio Divina Diária', 'Alimentando-se da Palavra', '{"intro": "A Lectio Divina \u00e9 um m\u00e9todo milenar de leitura orante da B\u00edblia. Diferente do estudo acad\u00eamico, ela busca o encontro pessoal com Deus atrav\u00e9s do texto sagrado. S\u00e3o quatro passos: Leitura (lectio), Medita\u00e7\u00e3o (meditatio), Ora\u00e7\u00e3o (oratio) e Contempla\u00e7\u00e3o (contemplatio). Mesmo 10 minutos por dia com este m\u00e9todo podem revolucionar sua rela\u00e7\u00e3o com a Escritura.", "prayer": "Esp\u00edrito Santo, abre meus olhos para ver as maravilhas da Tua lei. Que a Tua Palavra n\u00e3o seja apenas texto, mas vida para minha alma. Am\u00e9m.", "practice": "Escolha um Evangelho (sugerimos Marcos, o mais curto). Leia apenas um par\u00e1grafo por dia usando os 4 passos da Lectio Divina. Anote uma frase que tocou seu cora\u00e7\u00e3o.", "scripture": "\"L\u00e2mpada para os meus p\u00e9s \u00e9 a tua palavra, e luz para o meu caminho.\" \u2014 Sl 119,105", "reflection": "Qual foi a \u00faltima vez que uma passagem b\u00edblica realmente tocou seu cora\u00e7\u00e3o? O que aconteceria se voc\u00ea fizesse isso diariamente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('9f4f5035-2c4d-4b3b-9464-3406780937d7', 'a1b2c3d4-1111-4000-8000-000000000001', 4, 'O Exame de Consciência', 'Olhando o dia com os olhos de Deus', '{"intro": "O Exame de Consci\u00eancia, popularizado por Santo In\u00e1cio, \u00e9 uma ora\u00e7\u00e3o noturna poderosa. Em 5 passos simples, voc\u00ea revisa o dia com gratid\u00e3o, reconhece as mo\u00e7\u00f5es interiores, identifica onde falhou e planeja o amanh\u00e3. N\u00e3o \u00e9 uma sess\u00e3o de culpa \u2014 \u00e9 um momento de honestidade amorosa diante de Deus. Muitos santos consideravam esta a ora\u00e7\u00e3o mais importante do dia.", "prayer": "Senhor, ajuda-me a ver meu dia com Teus olhos. Onde falhei, d\u00e1-me Teu perd\u00e3o. Onde acertei, d\u00e1-me Tua humildade. Am\u00e9m.", "practice": "Hoje \u00e0 noite, fa\u00e7a o Exame em 5 passos: 1) Agrade\u00e7a; 2) Pe\u00e7a luz ao Esp\u00edrito; 3) Reveja o dia; 4) Pe\u00e7a perd\u00e3o; 5) Planeje o amanh\u00e3 com Deus.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "No final do dia, como voc\u00ea se sente? Consegue identificar momentos em que Deus agiu na sua vida hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('635e9a5e-6ba8-4189-ad69-2cdceb7f330a', 'a1b2c3d4-1111-4000-8000-000000000001', 5, 'Jejum e Silêncio', 'Esvaziando para ser preenchido', '{"intro": "O jejum n\u00e3o \u00e9 apenas abstin\u00eancia de comida \u2014 \u00e9 uma pr\u00e1tica de esvaziamento que abre espa\u00e7o para Deus. Jesus jejuou 40 dias no deserto antes de iniciar seu minist\u00e9rio. O sil\u00eancio interior, por sua vez, \u00e9 o terreno f\u00e9rtil onde a voz de Deus pode ser ouvida. Numa cultura de ru\u00eddo constante, aprender a silenciar \u00e9 um ato revolucion\u00e1rio de f\u00e9.", "prayer": "Deus do sil\u00eancio, ensina-me a esvaziar-me para ser preenchido por Ti. Que eu encontre no vazio a Tua plenitude. Am\u00e9m.", "practice": "Escolha um jejum para esta semana: redes sociais por 1 dia, ou sil\u00eancio de 30 minutos (sem m\u00fasica, sem podcast, sem conversa). Observe o que acontece no seu interior.", "scripture": "\"Mas tu, quando jejuares, unge a cabe\u00e7a e lava o rosto, para que n\u00e3o pare\u00e7as aos homens que jejuas.\" \u2014 Mt 6,17-18", "reflection": "De que forma o barulho (externo e interno) dificulta seu encontro com Deus? O que voc\u00ea poderia \"jejuar\" al\u00e9m de comida?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('39047abc-687a-4ad8-91f5-f383049ef091', 'a1b2c3d4-1111-4000-8000-000000000001', 6, 'Perseverança na Rotina', 'Quando a motivação acaba, a disciplina começa', '{"intro": "A maior tenta\u00e7\u00e3o da vida espiritual n\u00e3o \u00e9 o pecado grave \u2014 \u00e9 a mediocridade. \u00c9 o dia em que voc\u00ea \"n\u00e3o est\u00e1 com vontade\". Santa Teresa de \u00c1vila confessou que, por anos, sua ora\u00e7\u00e3o era \u00e1rida e sem consola\u00e7\u00e3o. Mas ela perseverou. E foi nos desertos que encontrou as maiores gra\u00e7as. A rotina espiritual n\u00e3o depende de sentir \u2014 depende de decidir, todos os dias.", "prayer": "Senhor, quando a aridez vier, lembra-me que Tu est\u00e1s presente mesmo no sil\u00eancio. D\u00e1-me a gra\u00e7a da perseveran\u00e7a. Am\u00e9m.", "practice": "Escreva sua Regra de Vida pessoal: hor\u00e1rio de ora\u00e7\u00e3o, leitura b\u00edblica, exame de consci\u00eancia. Cole em um lugar vis\u00edvel. Comprometa-se por 21 dias.", "scripture": "\"Aquele que perseverar at\u00e9 o fim, esse ser\u00e1 salvo.\" \u2014 Mt 24,13", "reflection": "Qual \u00e9 sua maior dificuldade para manter uma rotina espiritual? O que te faria n\u00e3o desistir mesmo nos dias dif\u00edceis?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
